<script lang="ts">
  import { ArrowsInSimple as Minimize2 } from "phosphor-svelte";
  import { contextPercentage, formatTokenCount, type CodexUsage } from "$lib/codex-protocol";
  let { usage, compacting = false, onCompact }: { usage: CodexUsage; compacting?: boolean; onCompact: () => void } = $props();
  let open = $state(false);
  const percent = $derived(contextPercentage(usage));
</script>
<div class="meter">
  <button class:overloaded={(percent ?? 0) > 90} aria-label={percent === null ? `${formatTokenCount(usage.totalTokens)} tokens used` : `Context window ${Math.round(percent)}% used`} onclick={() => (open = !open)}><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9" /><circle class="progress" cx="12" cy="12" r="9" style:stroke-dashoffset={56.55 * (1 - (percent ?? 0) / 100)} /></svg></button>
  {#if open}<section><header><strong>Context window</strong><span>{percent === null ? formatTokenCount(usage.totalTokens) : `${Math.round(percent)}%`}</span></header>{#if percent !== null}<div class="bar"><i style:width={`${percent}%`}></i></div><p>{formatTokenCount(usage.totalTokens)} of {formatTokenCount(usage.modelContextWindow ?? 0)} tokens</p>{/if}<dl><div><dt>Input</dt><dd>{formatTokenCount(usage.inputTokens)}</dd></div><div><dt>Cached</dt><dd>{formatTokenCount(usage.cachedInputTokens)}</dd></div><div><dt>Output</dt><dd>{formatTokenCount(usage.outputTokens)}</dd></div></dl><div class="thread-total"><span>Thread usage</span><strong>{formatTokenCount(usage.threadTotalTokens)} tokens</strong></div><button class="compact" disabled={compacting} onclick={onCompact}><Minimize2 size={12} />{compacting ? "Compacting…" : "Compact context"}</button></section>{/if}
</div>
